package clipboard

import (
	"slices"
	"strings"

	"github.com/yeisme/clavis/pkg/core/config"
)

// DefaultConcealedTypeMarkers lists cross-platform concealed/transient/password-manager pasteboard markers.
var DefaultConcealedTypeMarkers = []string{
	"org.nspasteboard.ConcealedType",
	"org.nspasteboard.TransientType",
	"org.nspasteboard.AutoGeneratedType",
	"com.agilebits.onepassword",
	"ExcludeClipboardContentFromMonitorProcessing",
	"CanIncludeInClipboardHistory",
	"x-kde-passwordManagerHint",
}

// PrivacyFilter decides whether a clipboard capture candidate should be recorded or ignored.
type PrivacyFilter struct {
	Enabled                 bool
	IgnoreConcealedTypes    bool
	ExcludedBundleIDs       map[string]struct{}
	IgnoreEmptyOrWhitespace bool
	ConcealedTypeMarkers    []string
}

// NewPrivacyFilter constructs a PrivacyFilter with defaults.
func NewPrivacyFilter() PrivacyFilter {
	return PrivacyFilter{
		Enabled:                 true,
		IgnoreConcealedTypes:    true,
		ExcludedBundleIDs:       make(map[string]struct{}),
		IgnoreEmptyOrWhitespace: true,
		ConcealedTypeMarkers:    append([]string(nil), DefaultConcealedTypeMarkers...),
	}
}

// NewPrivacyFilterFromConfig constructs a PrivacyFilter from config.ClipboardConfig.
func NewPrivacyFilterFromConfig(cfg config.ClipboardConfig) PrivacyFilter {
	excluded := make(map[string]struct{}, len(cfg.ExcludedBundleIDs))
	for _, id := range cfg.ExcludedBundleIDs {
		if trimmed := strings.TrimSpace(id); trimmed != "" {
			excluded[trimmed] = struct{}{}
		}
	}
	return PrivacyFilter{
		Enabled:                 cfg.Enabled,
		IgnoreConcealedTypes:    cfg.IgnoreConcealedTypes,
		ExcludedBundleIDs:       excluded,
		IgnoreEmptyOrWhitespace: true,
		ConcealedTypeMarkers:    append([]string(nil), DefaultConcealedTypeMarkers...),
	}
}

// DefaultSecretSourceProcesses are Windows password-manager / credential processes whose
// clipboard writes (text or images such as QR / recovery codes) are never recorded.
var DefaultSecretSourceProcesses = []string{
	"1password", "keepass", "keepassxc", "bitwarden", "enpass", "dashlane",
	"lastpass", "roboform", "credentialuibroker", "keychainaccess",
}

// ShouldRecord reports true if the candidate passes all privacy checks.
func (f PrivacyFilter) ShouldRecord(candidate CaptureCandidate) bool {
	content := candidate.Content
	if candidate.IsMedia() && strings.TrimSpace(content) == "" {
		// Media entries have no text; the empty-content rule must not drop them.
		content = string(candidate.Kind)
	}
	if isSecretSourceProcess(candidate.SourceBundleID) || isSecretSourceProcess(candidate.SourceAppName) {
		return false
	}
	return !f.ShouldIgnore(candidate.PasteboardTypes, candidate.SourceBundleID, content)
}

// isSecretSourceProcess matches Windows process names case-insensitively, ".exe" optional.
func isSecretSourceProcess(name string) bool {
	n := strings.TrimSuffix(strings.ToLower(strings.TrimSpace(name)), ".exe")
	if n == "" || strings.Contains(n, ".") {
		return false // macOS bundle IDs go through ExcludedBundleIDs
	}
	return slices.Contains(DefaultSecretSourceProcesses, n)
}

// ShouldIgnore reports true if the clipboard event must be skipped for privacy/policy reasons.
func (f PrivacyFilter) ShouldIgnore(pasteboardTypes []string, sourceBundleID, content string) bool {
	if !f.Enabled {
		return true
	}

	if f.IgnoreEmptyOrWhitespace {
		if strings.TrimSpace(content) == "" {
			return true
		}
	} else if content == "" {
		return true
	}

	if sourceBundleID != "" && len(f.ExcludedBundleIDs) > 0 {
		if _, excluded := f.ExcludedBundleIDs[sourceBundleID]; excluded {
			return true
		}
		for id := range f.ExcludedBundleIDs {
			if strings.EqualFold(id, sourceBundleID) {
				return true
			}
		}
	}

	if f.IgnoreConcealedTypes {
		markers := f.ConcealedTypeMarkers
		if len(markers) == 0 {
			markers = DefaultConcealedTypeMarkers
		}
		lowerMarkers := make([]string, len(markers))
		for i, m := range markers {
			lowerMarkers[i] = strings.ToLower(m)
		}
		for _, typ := range pasteboardTypes {
			lowerType := strings.ToLower(typ)
			for _, m := range lowerMarkers {
				if lowerType == m || strings.HasPrefix(lowerType, m+".") {
					return true
				}
			}
		}
	}

	return false
}
